        expected = {
            "AP-001": ("Elena Morales", "FX-17A / FX-17B"),
            "AP-002": ("Priya Nair", "FX-17A / FX-17B"),
            "AP-003": ("Grant Holloway", "FX-17A / FX-17B"),
        }
        found = {}
        for row in range(6, ws.max_row + 1):
            appraiser_id = ws.cell(row, id_col).value
            if appraiser_id in expected:
                found[appraiser_id] = (
                    ws.cell(row, name_col).value,
                    ws.cell(row, scope_col).value,
                )
        ok = all(
            appraiser_id in found
            and _norm(found[appraiser_id][0]) == _norm(name)
            and _norm(found[appraiser_id][1]) == _norm(scope)
            and "fx-17c" not in _norm(found[appraiser_id][1])
            for appraiser_id, (name, scope) in expected.items()
        )
        return {
            "score": 1 if ok else 0,
