import sqlite3
from pathlib import Path

TARGETS = {
    "PAY-20250324-00671": {"amount_cent": 1248765327, "version_before": 4},
    "PAY-20250324-00672": {"amount_cent": 631894786, "version_before": 4},
}
INCIDENT = "INC-PAY-2025-0324-01"


def _db(workspace):
    workspace = Path(workspace)
    return workspace.parent / "system" / "treasury_payment_hub" / "state.db"


def _connect(workspace):
    connection = sqlite3.connect(_db(workspace))
    connection.row_factory = sqlite3.Row
    return connection


def check_incident_tag_and_version(workspace):
    with _connect(workspace) as connection:
        rows = connection.execute(
            "SELECT instruction_id, incident_id, version, status, amount_cent "
            "FROM payment_instructions WHERE instruction_id IN (?, ?) ORDER BY instruction_id",
            tuple(TARGETS),
        ).fetchall()
    if len(rows) != 2:
        return {"score": 0, "detail": "目标指令记录不完整"}
    errors = []
    for row in rows:
        expected = TARGETS[row["instruction_id"]]
        if row["incident_id"] != INCIDENT:
            errors.append(f"{row['instruction_id']} incident_id={row['incident_id']!r}")
        if row["version"] != expected["version_before"] + 1:
            errors.append(f"{row['instruction_id']} version={row['version']}")
        if row["status"] != "EXECUTED":
            errors.append(f"{row['instruction_id']} status={row['status']!r}")
        if row["amount_cent"] != expected["amount_cent"]:
            errors.append(f"{row['instruction_id']} amount_cent={row['amount_cent']}")
    return {"score": 0 if errors else 1, "detail": "; ".join(errors) if errors else "两条指令事件标识、版本及核心支付事实正确"}


def check_review_audit_records(workspace):
    with _connect(workspace) as connection:
        rows = connection.execute(
            "SELECT instruction_id, status_code, event_sequence, event_source, operator_id, remark "
            "FROM instruction_status_log WHERE instruction_id IN (?, ?) "
            "AND status_code='REVIEWED' AND event_source='OPERATIONS' AND operator_id='PERSON-incident-ops' "
            "ORDER BY instruction_id, event_sequence",
            tuple(TARGETS),
        ).fetchall()
    errors = []
    found = {key: [] for key in TARGETS}
    for row in rows:
        found[row["instruction_id"]].append(row)
    for instruction_id, entries in found.items():
        if len(entries) != 1:
            errors.append(f"{instruction_id} 操作审计记录数={len(entries)}")
            continue
        entry = entries[0]
        if entry["event_sequence"] != 5:
            errors.append(f"{instruction_id} event_sequence={entry['event_sequence']}")
        remark = entry["remark"] or ""
        if "重复" not in remark or "事件" not in remark:
            errors.append(f"{instruction_id} 审计原因未说明重复付款事件归属")
    return {"score": 0 if errors else 1, "detail": "; ".join(errors) if errors else "两条指令各有一条 REVIEWED 复盘审计记录"}


def check_unchanged_payment_facts(workspace):
    with _connect(workspace) as connection:
        rows = connection.execute(
            "SELECT instruction_id, incident_id, version, status, amount_cent "
            "FROM payment_instructions WHERE instruction_id IN (?, ?, ?) ORDER BY instruction_id",
            ("PAY-20250324-00671", "PAY-20250324-00672", "PAY-20250324-00679"),
        ).fetchall()
    by_id = {row["instruction_id"]: row for row in rows}
    errors = []
    for instruction_id, expected in TARGETS.items():
        row = by_id.get(instruction_id)
        if not row or row["status"] != "EXECUTED" or row["amount_cent"] != expected["amount_cent"]:
            errors.append(f"{instruction_id} 金额或执行状态被改变")
    unrelated = by_id.get("PAY-20250324-00679")
    if not unrelated or unrelated["incident_id"] is not None or unrelated["version"] != 3 or unrelated["status"] != "EXECUTED" or unrelated["amount_cent"] != 169339887:
