def _sha256(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _workspace_hash(workspace):
    digest = hashlib.sha256()
    files = []
    for path in workspace.rglob("*"):
        if not path.is_file():
            continue
        relative = path.relative_to(workspace).as_posix()
        if relative == "answer.md":
            continue
        files.append((relative, path))
    for relative, path in sorted(files):
        digest.update(relative.encode("utf-8"))
        digest.update(b"\0")
        digest.update(hashlib.sha256(path.read_bytes()).digest())
    return digest.hexdigest()


def check_read_only_integrity(workspace):
    changed = []
    if _workspace_hash(workspace) != _EXPECTED_WORKSPACE_HASH:
        changed.append("workspace")
    system = workspace.parent / "system"
    for name, expected in _EXPECTED_DATABASE_HASHES.items():
        path = system / name / "state.db"
        if not path.is_file() or _sha256(path) != expected:
            changed.append(name + "/state.db")
    if changed:
        return {"score": 0, "detail": "Read-only integrity failed: " + ", ".join(changed)}
    return {"score": 1, "detail": "Workspace and all source databases match the initial state."}

